content.content:
"use client";

// "Explain this mod": everything the build reported, in plain English, set as a
// readable document (type and hairlines, not boxes). Also the request and the images
// Cyrus looked at, and the failure explanation with retry.
import { useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { cyrusModel } from "@/lib/cyrus/models";
import { viewMeta } from "@/lib/cyrus/projects";
import { estimate } from "@/lib/cyrus/estimate";
import { CyIcon, CyrusBadge, ModelMark } from "./icons";

export function Explain({ b }: { b: ModBuildView }) {
  const r = b.result;
  const s = r?.summary;
  if (b.status !== "succeeded") return <div className="cy-doc">{b.status === "failed" && <FailureDetails b={b} />}<Request b={b} lead={b.status !== "failed"} /></div>;
  return (
    <div className="cy-doc">
      <section className="cy-doc-hero">
        <span className="cy-k"><CyIcon name="explain" size={12} /> In plain English</span>
        <h3>{s?.tagline || `${b.pluginName} is built`}</h3>
        {s?.text && <p className="cy-lead">{s.text}</p>}
        {s?.changes && b.changeRequest && <p className="cy-changed"><b>What changed.</b> {s.changes}</p>}
      </section>

      {!!s?.howToUse?.length && (
        <section className="cy-doc-s">
          <h4>How to use it</h4>
          <ol className="cy-steps">{s.howToUse.map((h, i) => <li key={i}><span className="cy-step-n">{i + 1}</span><span>{h}</span></li>)}</ol>
        </section>
      )}

      {!!r?.commands?.length && (
        <section className="cy-doc-s">
          <h4>Commands <span className="cy-count">{r.commands.length}</span></h4>
          <div className="cy-rows">
            {r.commands.map((c, i) => (
              <div key={i} className="cy-row">
                <code className="cy-cmd">{c.usage}</code>
                <span className="cy-row-v">{c.description}</span>
                <span className={`cy-who ${/every/i.test(c.whoCanUse) || (!c.whoCanUse && !c.permission) ? "all" : ""}`}>{c.whoCanUse || (c.permission ? "With permission" : "Everyone")}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {!!r?.config?.length && (
        <section className="cy-doc-s">
          <h4>Settings you can change</h4>
          <p className="cy-sub">In <code className="cy-cmd">plugins/{b.pluginName}/config.yml</code> on your server.</p>
          <div className="cy-rows">
            {r.config.map((c, i) => (
              <div key={i} className="cy-row">
                <b className="cy-anywhere cy-row-k">{c.key}</b>
                <span className="cy-row-v">{c.description}</span>
                <span className="cy-row-d cy-anywhere">{c.default ? `Default ${c.default}` : ""}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {!!r?.permissions?.length && (
        <section className="cy-doc-s">
          <h4>Who can do what</h4>
          <p className="cy-sub">Works with LuckPerms or any permissions plugin.</p>
          <div className="cy-rows">
            {r.permissions.map((p, i) => (
              <div key={i} className="cy-row">
                <b className="cy-anywhere cy-row-k">{p.node}</b>
                <span className="cy-row-v">{p.description}</span>
                <span className={`cy-who ${p.default === "true" ? "all" : ""}`}>{p.default === "true" ? "Everyone" : p.default === "false" ? "Nobody by default" : "Operators"}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      <Safety b={b} />

      {(!!s?.limitations?.length || !!r?.warnings?.length) && (
        <section className="cy-doc-s">
          <h4>Good to know</h4>
          <ul className="cy-bullets">
            {(s?.limitations ?? []).map((l, i) => <li key={`l${i}`}>{l}</li>)}
            {(r?.warnings ?? []).slice(0, 6).map((w, i) => <li key={`w${i}`}>{w}</li>)}
          </ul>
        </section>
      )}

      <Request b={b} />

      <section className="cy-doc-s cy-soon">
        <CyrusBadge version={b.version ? `v${b.version}` : null} />
        <p className="cy-sub">Coming to Cyrus mods: your server&apos;s Mods tab with an on/off switch, a Cyrus Mods community in NxLabs, and open source so anyone can learn from them.</p>
      </section>
    </div>
  );
}

export function Request({ b, lead }: { b: ModBuildView; lead?: boolean }) {
  const meta = viewMeta(b);
  const atts = meta.attachments ?? [];
  const m = cyrusModel(meta.model);
  const running = !isTerminal(b.status);
  const e = running ? estimate(b.changeRequest || b.prompt, m.id, { change: !!b.changeRequest }) : null;
  return (
    <section className={`cy-doc-s ${lead ? "lead" : ""}`}>
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
      {b.changeRequest && <details className="cy-details"><summary>Original description</summary><p>{b.prompt}</p></details>}
      {atts.length > 0 && (
        <div className="cy-refs">
          {atts.map((a) => (
            <a key={a.n} href={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} target="_blank" rel="noreferrer" className="cy-ref" title={a.name}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} alt={a.name} loading="lazy" />
            </a>
          ))}
          <span className="cy-sub"><CyIcon name="eye" size={12} /> {atts.length === 1 ? "Cyrus looked at this image" : `Cyrus looked at these ${atts.length} images`} while planning.</span>
        </div>
      )}
      {lead && (
        <p className="cy-fine">
          <ModelMark tier={m.spend} /> {m.name} · Paper {b.mcVersion}
          {e && <> · usually ~{e.minutes[0]}–{e.minutes[1]} min</>}
        </p>
      )}
    </section>
  );
}

function Safety({ b }: { b: ModBuildView }) {
  const sf = b.result?.safety;
  const warns = (sf?.findings ?? []).filter((f) => f.severity === "warn");
  const checks: [string, string][] = [
    ["No internet access", "It can't send your data anywhere."],
    ["Can't run programs", "Nothing outside the game gets started."],
    ["Only its own folder", `Reads and writes only plugins/${b.pluginName || ""}.`],
    ["No hidden admin access", "No secret players with special powers."],
  ];
  return (
    <section className="cy-doc-s cy-safety">
      <h4><span className="cy-shield"><CyIcon name="shield" size={14} /></span> Safety check <span className={`cy-pill ${warns.length ? "warn" : "ok"}`}><i />{warns.length ? "Passed with notes" : "Passed"}</span></h4>
      <ul className="cy-checks">
        {checks.map(([t, d]) => <li key={t}><CyIcon name="check" size={13} strokeWidth={2.2} /><span><b>{t}</b> {d}</span></li>)}
      </ul>
      {warns.length > 0 && <p className="cy-note">This mod {Array.from(new Set(warns.map((w) => w.message))).join("; ")}. That&apos;s allowed, just worth knowing.</p>}
      <p className="cy-fine">An automated scan of the compiled code. It checks for risky behaviour; it doesn&apos;t promise the mod is bug-free.</p>
    </section>
  );
}

const FAIL: Record<string, { title: string; tips: string[] }> = {
  compile: { title: "The code didn't compile, even after fixes", tips: ["Ask for fewer features at once. You can add more as changes afterwards.", "Avoid asking for other plugins (like Vault or WorldEdit). Cyrus builds on plain Paper."] },
  safety: { title: "Blocked by the safety check", tips: ["Remove anything that needs the internet, other programs or files outside the server.", "Webhooks, Discord bots and remote databases can't be built yet."] },
  refused: { title: "Cyrus won't build this one", tips: ["Cyrus only builds mods that are safe for your players and your server."] },
  budget: { title: "This mod is bigger than one build", tips: ["Split the idea into two or three smaller mods, or try Yakko for big systems."] },
  timeout: { title: "This build ran out of time", tips: ["Split the idea into two or three smaller mods."] },
  cancelled: { title: "You stopped this build", tips: ["Start it again whenever you like."] },
  ai_unavailable: { title: "Cyrus had a hiccup", tips: ["Trying again in a minute usually works."] },
  unavailable: { title: "The builder is offline", tips: ["Try again in a few minutes."] },
  interrupted: { title: "The builder restarted mid-build", tips: ["Nothing is lost. Start it again."] },
};

const failInfo = (b: ModBuildView) => FAIL[b.errorCode || ""] ?? { title: "This one didn't build", tips: ["Try again, or describe it a little differently."] };

/** Failure details, at the top of the inspector's Request tab. */
export function FailureDetails({ b }: { b: ModBuildView }) {
  const f = failInfo(b);
  return (
    <section className="cy-doc-s lead cy-faild">
      <span className="cy-fail-k"><CyIcon name={b.errorCode === "cancelled" ? "stop" : "warn"} size={13} /> {b.errorCode === "cancelled" ? "Stopped" : "Why it didn't build"}</span>
      {b.error && <p className="cy-lead">{b.error}</p>}
      <ul className="cy-bullets">{f.tips.map((t) => <li key={t}>{t}</li>)}</ul>
      {b.result?.errorDetail && b.errorCode === "compile" && (
        <details className="cy-details"><summary>What the compiler said</summary><pre className="cy-pre">{b.result.errorDetail}</pre></details>
      )}
    </section>
  );
}

/** Failure, shown under the core on the web: the verdict and the two ways forward. */
export function Failure({ b, onRetry, onEdit }: { b: ModBuildView; onRetry: () => Promise<string | null>; onEdit: () => void }) {
  const f = failInfo(b);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  return (
    <div className={`cy-fail code-${b.errorCode}`}>
      <span className="cy-fail-k"><CyIcon name={b.errorCode === "cancelled" ? "stop" : "warn"} size={13} /> {b.errorCode === "cancelled" ? "Stopped" : "Didn't build"}</span>
      <h2 className="cy-fail-t">{f.title}</h2>
      {err && <p className="cy-err" role="alert">{err}</p>}
      <div className="cy-fail-act">
        {b.errorCode !== "refused" && (
          <button type="button" className="cy-btn primary" disabled={busy} onClick={async () => { setBusy(true); setErr(await onRetry()); setBusy(false); }}>
            {busy ? <i className="cy-spin" /> : <CyIcon name="retry" size={14} />} Try again
          </button>
        )}
        <button type="button" className="cy-btn" onClick={onEdit}><CyIcon name="pencil" size={14} /> {b.errorCode === "refused" ? "Describe something else" : "Edit and retry"}</button>
      </div>
    </div>
  );
}
"use client";

// The right inspector (owner concept): actions (Share, more, Deploy Mod), tabs Code / Explain /
// Versions / Files / Notes, and under the code the mod card (name, version + loader chips,
// description or the live build, Open Project / Download / NxLabs) with its Related Files.
import { useEffect, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_STATUS_LABEL, CYRUS_STAGES } from "@/lib/cyrus/models";
import { versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CYRUS_NOTES_MAX, type ProjectPatch } from "@/lib/cyrus/meta";
import { cyrusCategory } from "@/lib/cyrus/categories";
import { CYRUS_TEMPLATES, type CyrusTemplate } from "@/lib/cyrus/templates";
import { LiveCode, FilesList, useFolders } from "./LiveCode";
import { Explain, Failure } from "./Explain";
import { Versions } from "./Versions";
import { InstallModal } from "./Modals";
import { CyIcon, CyrusBadge, ModCube } from "./icons";
import { projectCategory } from "./web/tree-layout";
import { STAGE_HEADLINE } from "./web/scenes";
import type { LiveState } from "./useLive";
import { ago, bytes, dur, isTypingTarget } from "./util";

export type Tab = "code" | "explain" | "versions" | "files" | "notes";

export function Inspector({ project, viewing, servers, live, tab, setTab, focusPath, onPickFile, onOpen, onPatch, onDuplicate, onRefresh, onRetry, onEdit, onOpenProject, onUseTemplate, onToast, wide, onWide }: {
  project: CyrusProject | null;
  viewing: ModBuildView | null;
  servers: MbServer[];
  live: LiveState;
  tab: Tab;
  setTab: (t: Tab) => void;
  focusPath: string | null;
  onPickFile: (path: string | null) => void;
  onOpen: (id: string) => void;
  onPatch: (rootId: string, patch: ProjectPatch) => Promise<string | null>;
  onDuplicate: (p: CyrusProject) => Promise<string | null>;
  onRefresh: () => void;
  onRetry: () => Promise<string | null>;
  onEdit: () => void;
  onOpenProject: (p: CyrusProject) => void;
  onUseTemplate: (t: CyrusTemplate) => void;
  onToast: (text: string) => void;
  wide: boolean;
  onWide: () => void;
}) {
  const [modal, setModal] = useState<null | "install">(null);
  const [menu, setMenu] = useState(false);
  const [folder, setFolder] = useState<string | null>(null);
  const b = viewing;
  useEffect(() => { setMenu(false); }, [b?.id]);

  // 1-5 switch tabs, F favourites
  useEffect(() => {
    if (!project) return;
    const k = (e: KeyboardEvent) => {
      if (isTypingTarget(e.target) || e.metaKey || e.ctrlKey || e.altKey || document.querySelector(".cy-modal-back")) return;
      const t = ({ "1": "code", "2": "explain", "3": "versions", "4": "files", "5": "notes" } as Record<string, Tab>)[e.key];
      if (t) { setTab(t); e.preventDefault(); }
      if (e.key === "f" || e.key === "F") { onPatch(project.rootId, { favourite: !project.meta.favourite }); e.preventDefault(); }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [project, onPatch, setTab]);

  if (!project || !b) return <aside className="cy-insp empty" aria-label="Get started"><Welcome onUse={onUseTemplate} /></aside>;

  const running = !isTerminal(b.status);
  const ok = b.status === "succeeded";
  const parent = b.baseBuildId ? project.builds.find((x) => x.id === b.baseBuildId) ?? null : null;
  const tabs: { id: Tab; label: string; icon: string; n?: number; dot?: boolean }[] = [
    { id: "code", label: "Code", icon: "code", dot: running },
    { id: "explain", label: ok ? "Explain" : "Request", icon: "explain" },
    { id: "versions", label: "Versions", icon: "branch", n: project.builds.length },
    { id: "files", label: "Files", icon: "folder" },
    { id: "notes", label: "Notes", icon: "docs" },
  ];
  const share = async () => {
    try { await navigator.clipboard.writeText(window.location.origin + `/dashboard/cyrus/${b.id}`); onToast("Link copied. During the preview only you can open it."); }
    catch { onToast("Couldn't copy the link."); }
  };

  return (
    <aside className={`cy-insp ${wide ? "wide" : ""}`} aria-label={`${project.title} details`}>
      <div className="cy-insp-act">
        <button type="button" className="cy-btn" onClick={share}><CyIcon name="share" size={16} /> <span>Share</span></button>
        <span className="relative">
          <button type="button" className="cy-btn icon" aria-label="More" aria-expanded={menu} onClick={() => setMenu((v) => !v)}><CyIcon name="more" size={17} /></button>
          {menu && (
            <span className="cy-menu" role="menu" onMouseLeave={() => setMenu(false)}>
              {ok && <a role="menuitem" href={`/api/mod-builder/builds/${b.id}/jar`} download><CyIcon name="download" size={15} /> Download .jar</a>}
              {ok && <a role="menuitem" href={`/api/mod-builder/builds/${b.id}/source-zip`}><CyIcon name="download" size={15} /> Download source (.zip)</a>}
              <button type="button" role="menuitem" onClick={async () => { setMenu(false); await onDuplicate(project); }}><CyIcon name="copy" size={15} /> Duplicate as a new mod</button>
              <button type="button" role="menuitem" onClick={() => { setMenu(false); navigator.clipboard?.writeText(b.changeRequest || b.prompt); onToast("Request copied."); }}><CyIcon name="docs" size={15} /> Copy the request</button>
              {running && <button type="button" role="menuitem" onClick={async () => { setMenu(false); await fetch(`/api/mod-builder/builds/${b.id}/cancel`, { method: "POST" }); onRefresh(); }}><CyIcon name="stop" size={15} /> Stop this build</button>}
            </span>
          )}
        </span>
        <button type="button" className="cy-btn primary" disabled={!ok} onClick={() => setModal("install")} title={ok ? "Install this version on one of your servers" : "Deploy becomes available when the build is ready"}>
          <CyIcon name="deploy" size={16} /> <span>Deploy Mod</span>
        </button>
      </div>

      <section className="cy-insp-panel">
        <div className="cy-tabs" role="tablist">
          {tabs.map((t, i) => (
            <button key={t.id} type="button" role="tab" aria-selected={tab === t.id} className={`cy-tab ${tab === t.id ? "on" : ""}`} onClick={() => { setTab(t.id); if (t.id !== "files") setFolder(null); }} title={`${t.label}  ${i + 1}`}>
              {tab === t.id && <CyIcon name={t.icon} size={15} tone="violet" />}
              {t.label}{t.n !== undefined && <span className="cy-tab-n">{t.n}</span>}
              {t.dot && <i className="cy-dotpulse" aria-label="Live" />}
            </button>
          ))}
        </div>
        <div className="cy-insp-body" role="tabpanel">
          {tab === "code" && (
            <>
              <LiveCode build={b} base={parent} live={live} focusPath={focusPath} onPick={(p) => onPickFile(p)} wide={wide} onWide={onWide} />
              <ModCard project={project} b={b} live={live} parent={parent} onOpenProject={() => onOpenProject(project)} onPatch={onPatch} onOpen={onOpen}
                       onRetry={onRetry} onEdit={onEdit} onFolder={(f) => { setFolder(f); setTab("files"); }} />
            </>
          )}
          {tab === "explain" && <Explain b={b} />}
          {tab === "versions" && (
            <Versions project={project} viewing={b.id} onOpen={onOpen}
                      onRestore={async (id) => { await onPatch(project.rootId, { headBuildId: id }); }}
                      onBranch={(id) => { onOpen(id); onToast(`Ask for a change: it builds on v${versionNumber(project, id)}.`); }} />
          )}
          {tab === "files" && <FilesList build={b} base={parent} live={live} folder={folder} onOpen={(p) => { onPickFile(p); setTab("code"); }} />}
          {tab === "notes" && <Notes key={project.rootId} project={project} onPatch={onPatch} />}
        </div>
      </section>
      {modal === "install" && <InstallModal build={b} servers={servers} onClose={() => setModal(null)} onDone={onRefresh} />}
    </aside>
  );
}

function ModCard({ project, b, live, parent, onOpenProject, onPatch, onOpen, onRetry, onEdit, onFolder }: {
  project: CyrusProject; b: ModBuildView; live: LiveState; parent: ModBuildView | null;
  onOpenProject: () => void; onPatch: (rootId: string, p: ProjectPatch) => Promise<string | null>; onOpen: (id: string) => void;
  onRetry: () => Promise<string | null>; onEdit: () => void; onFolder: (f: string) => void;
}) {
  const [rename, setRename] = useState(false);
  const cat = cyrusCategory(projectCategory(project));
  const running = !isTerminal(b.status);
  const ok = b.status === "succeeded";
  const s = b.result?.summary;
  const folders = useFolders(b, parent, live);
  const n = versionNumber(project, b.id);
  const isHead = project.head?.id === b.id;
  return (
    <section className="cy-mod">
      <header className="cy-mod-h">
        <span className="cy-mod-ic" style={{ ["--hue" as string]: cat.hue }}><ModCube hue={cat.hue} size={24} /></span>
        {rename ? (
          <form className="cy-rename" onSubmit={async (e) => { e.preventDefault(); const v = String(new FormData(e.currentTarget).get("t") || ""); await onPatch(project.rootId, { title: v || null }); setRename(false); }}>
            <input name="t" autoFocus defaultValue={project.title} maxLength={60} aria-label="Mod name" onBlur={(e) => e.currentTarget.form?.requestSubmit()} onKeyDown={(e) => { if (e.key === "Escape") setRename(false); }} />
          </form>
        ) : <h3 className="cy-mod-t" onDoubleClick={() => setRename(true)} title="Double-click to rename">{project.title}</h3>}
        <button type="button" className={`cy-ib star ${project.meta.favourite ? "on" : ""}`} aria-pressed={!!project.meta.favourite} aria-label="Favourite" title="Favourite  F"
                onClick={() => onPatch(project.rootId, { favourite: !project.meta.favourite })}><CyIcon name="star" size={15} fill={!!project.meta.favourite} /></button>
        <span className="cy-chip ver">{b.mcVersion}</span>
        <span className="cy-chip">Paper</span>
        <span className="cy-chip dim" title={`Version ${n} of ${project.builds.length}`}>v{n}</span>
      </header>
      {!isHead && ok && project.head && (
        <p className="cy-mod-older"><CyIcon name="history" size={13} /> Viewing v{n}. Current is v{versionNumber(project, project.head.id)}.
          <button type="button" onClick={() => onPatch(project.rootId, { headBuildId: b.id })}>Make v{n} current</button>
          <button type="button" onClick={() => onOpen(project.head!.id)}>Go to current</button></p>
      )}
      {running ? <BuildStrip b={b} /> : b.status === "failed" ? <Failure b={b} onRetry={onRetry} onEdit={onEdit} /> : (
        <p className="cy-mod-d">{s?.text || s?.tagline || b.prompt}</p>
      )}
      <div className="cy-mod-act">
        <button type="button" className="cy-btn primary" onClick={onOpenProject}><CyIcon name="cube" size={15} /> Open Project <CyIcon name="external" size={14} /></button>
        {ok ? <a className="cy-btn" href={`/api/mod-builder/builds/${b.id}/jar`} download title={b.jarName ? `${b.jarName} · ${bytes(b.jarSize)}` : undefined}><CyIcon name="download" size={15} /> Download</a>
          : <button type="button" className="cy-btn" disabled><CyIcon name="download" size={15} /> Download</button>}
        <button type="button" className="cy-btn" disabled title="Publishing Cyrus mods to NxLabs is coming soon"><CyIcon name="link" size={15} /> View on NxLabs</button>
      </div>
      {folders.length > 0 && (
        <div className="cy-rel">
          <h4>Related Files</h4>
          {folders.map(([f, c]) => (
            <button key={f} type="button" className="cy-rel-r" onClick={() => onFolder(f)}>
              <CyIcon name="folder" size={18} tone="blue" fill />
              <span>{f}</span>
              <em>{c} file{c === 1 ? "" : "s"}</em>
              <CyIcon name="chevr" size={15} />
            </button>
          ))}
        </div>
      )}
      {ok && <div className="cy-mod-foot"><CyrusBadge version={b.version ? `v${b.version}` : null} /><span>{b.pluginName} · built in {dur(b.durationMs)}{b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}</span></div>}
    </section>
  );
}

/** The live build: stage track, headline, elapsed, last thoughts. */
function BuildStrip({ b }: { b: ModBuildView }) {
  const events = b.result?.events ?? [];
  const startedAt = events.find((e) => e.stage !== "queued")?.at ?? null;
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, []);
  const order = ["planning", "coding", "compiling", "repairing", "scanning", "succeeded"];
  const cur = order.indexOf(b.status === "queued" ? "planning" : b.status);
  const repairs = b.result?.repairs ?? 0;
  const stream = events.filter((e) => e.stage !== "queued" && e.message && e.message !== "Error details" && e.message !== "API lookup").slice(-3);
