const BASE = "/dashboard/cyrus";

export function CyrusApp({ initialBuilds, servers, online, userId, selectedId }: { initialBuilds: ModBuildView[]; servers: MbServer[]; online: boolean; userId: string; selectedId: string | null }) {
  useCyrusBoot(userId);

  // The real account, before the first paint of the network. Never during render: the store is a
  // module singleton, and on the server it would be shared between requests (accounts).
  useLayoutEffect(() => {
    const s = useStore.getState();
    s.setReal(initialBuilds);
    useStore.setState({ servers, online });
    // Deep link (/dashboard/cyrus/<buildId>): open that mod. Otherwise re-attach to a running build.
    const b = selectedId ? s.realBuilds.find((x) => x.id === selectedId) : null;
    if (b) {
      const mod = findMod(realModId(b.rootBuildId ?? b.id));
      if (mod) s.select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true, focus: "path" });
    }
    const running = s.realBuilds.filter((x) => !isTerminal(x.status)).sort((a, c) => c.createdAt.localeCompare(a.createdAt))[0];
    if (running) void followForge(running.id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The URL follows the selected real mod (shareable during the preview, like v4).
  const selection = useStore((s) => s.selection);
  const real = useStore((s) => s.real);
  useEffect(() => {
    const id = selection.level === "mod" && selection.modId?.startsWith("nx-") ? real.active[selection.modId] : null;
    const url = id ? `${BASE}/${id}` : BASE;
    if (window.location.pathname !== url) window.history.replaceState(window.history.state, "", url);
  }, [selection, real]);

  // Keep the account fresh: other running builds (two at a time), and everything every 30 s.
  const builds = useStore((s) => s.realBuilds);
  const followed = useStore((s) => (isJobLive(s.job) ? s.job?.buildId : undefined));
  useEffect(() => {
    const ids = builds.filter((b) => !isTerminal(b.status) && b.id !== followed).map((b) => b.id);
    if (!ids.length) return;
    const t = window.setTimeout(async () => {
      const res = await Promise.all(ids.map((id) => fetch(`/api/mod-builder/builds/${id}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).catch(() => null)));
      const fresh = res.filter(Boolean).map((j) => j.build as ModBuildView);
      if (fresh.length) useStore.getState().upsertReal(fresh);
    }, document.visibilityState === "hidden" ? 9000 : 4000);
    return () => window.clearTimeout(t);
  }, [builds, followed]);
  useEffect(() => {
    const t = window.setInterval(() => void useStore.getState().refreshReal(), 30_000);
    return () => window.clearInterval(t);
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const s = useStore.getState();
      const target = e.target as HTMLElement | null;
      const typing = !!target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable);
      if (document.querySelector(".cy-modal-back")) return; // the token / install modal owns the keys
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        // Cyrus's own palette wins over the portal's while the studio is open.
        e.preventDefault();
        e.stopImmediatePropagation();
        s.setPaletteOpen(!s.paletteOpen);
        return;
      }
      if (s.paletteOpen || s.addGameOpen) return;
      if (e.key === "Escape") {
        if (typing) {
          target?.blur();
          return;
        }
        if (s.selection.level !== "core") s.goUp();
        else if (s.panelOpen) s.setPanelOpen(false);
        return;
      }
      if (typing) return;
      if (e.key === "/") {
        e.preventDefault();
        s.focusPrompt();
      }
    };
    // capture: runs before the portal shell's own Ctrl/⌘K listener (bubble, on window)
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, []);

  return (
    <div className="fixed inset-0 overflow-hidden">
      <CosmosBackground />
      <Network />
      <TopBar />
      <ZoomControls />
      <PreviewPanel />
      <PromptDock />
      <CommandPalette />
      <AddGameDialog />
      <Toasts />
      <CyrusTokensHost />
    </div>
  );
}
"use client";

import { useEffect, useState, type ReactNode } from "react";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { GameEmblem } from "@/components/cyrus/icons/GameEmblems";
import { CloseIcon, CodeIcon, DownloadIcon, FolderIcon, HistoryIcon, NoteIcon } from "@/components/cyrus/icons/ui";
import { InstallModal } from "@/components/cyrus/kit/InstallModal";
import { isTerminal } from "@/lib/modbuilder/types";
import { CATEGORY_BY_KEY, slugify } from "@/lib/cyrus/data";
import { getGame, isJobLive, useGame, useMod, useModVersions, useStore, type PanelTab } from "@/lib/cyrus/store";
import { downloadBlob, zipFiles } from "@/lib/cyrus/zip";
import { BranchOverview } from "./BranchOverview";
import { CodeView, FileTabs } from "./CodeView";
import { FilesTab } from "./FilesTab";
import { NotesTab } from "./NotesTab";
import { VersionsTab } from "./VersionsTab";

const TABS: { id: PanelTab; label: string; icon: ReactNode }[] = [
  { id: "code", label: "Code", icon: <CodeIcon /> },
  { id: "files", label: "Files", icon: <FolderIcon /> },
  { id: "versions", label: "Versions", icon: <HistoryIcon /> },
  { id: "notes", label: "Notes", icon: <NoteIcon /> },
];

function PanelShell({ children }: { children: ReactNode }) {
  return (
    <aside
      className="cy5-glass animate-slide-right fixed inset-x-2 bottom-2 top-[68px] z-40 flex flex-col overflow-hidden rounded-[22px] lg:inset-x-auto lg:bottom-5 lg:right-5 lg:top-[76px] lg:w-[min(540px,calc(40cqw-20px))]"
      aria-label="Preview panel"
    >
      {children}
    </aside>
  );
}

export function PreviewPanel() {
  const open = useStore((s) => s.panelOpen);
  const selection = useStore((s) => s.selection);
  const setPanelOpen = useStore((s) => s.setPanelOpen);
  if (!open) return null;
  if (selection.level !== "mod" || !selection.modId) return <OverviewPanel onClose={() => setPanelOpen(false)} />;
  return <ModPanel modId={selection.modId} onClose={() => setPanelOpen(false)} />;
}

function OverviewPanel({ onClose }: { onClose: () => void }) {
  const selection = useStore((s) => s.selection);
  const game = useGame(selection.gameId);
  const cat = selection.category ? CATEGORY_BY_KEY[selection.category] : undefined;
  const rgb = cat?.rgb ?? game?.rgb ?? "167 139 250";
  return (
    <PanelShell>
      <header className="tint hairline-top flex items-center gap-3 px-5 pb-4 pt-5" style={{ ["--c" as string]: rgb }}>
        <span
          className={`grid h-11 w-11 shrink-0 place-items-center text-[22px] ${cat ? "rotate-45 rounded-[13px]" : "rounded-full"}`}
          style={{ color: "var(--cc)", background: `rgb(${rgb} / 0.14)`, boxShadow: `inset 0 0 0 1px rgb(${rgb} / 0.45), 0 0 24px rgb(${rgb} / 0.3)` }}
        >
          {cat ? (
            <CategoryIcon k={cat.key} className="-rotate-45" />
          ) : game ? (
            <GameEmblem emblem={game.emblem} logo={game.logo} logoTone={game.logoTone} />
          ) : (
            <span className="h-4 w-4 rounded-full bg-gradient-to-br from-white via-cy-accent to-cy-cyan shadow-[0_0_16px_var(--accent)]" />
          )}
        </span>
        <div className="min-w-0 flex-1">
          <div className="text-[10.5px] font-semibold uppercase tracking-[0.18em] text-cy-muted">
            {cat ? `${game?.name} · Category` : game ? `Game · ${game.toolchain}` : "Network overview"}
          </div>
          <h2 className="truncate font-cy-display text-[19px] font-semibold text-cy-ink">{cat?.label ?? game?.name ?? "Cyrus Core"}</h2>
        </div>
        <button type="button" onClick={onClose} className="cy5-btn-ghost h-9 w-9 text-cy-muted" aria-label="Close panel">
          <CloseIcon />
        </button>
      </header>
      <BranchOverview selection={selection} />
    </PanelShell>
  );
}

function ModPanel({ modId, onClose }: { modId: string; onClose: () => void }) {
  const mod = useMod(modId);
  const { versions, active } = useModVersions(mod);
  const job = useStore((s) => s.job);
  const tab = useStore((s) => s.panelTab);
  const setTab = useStore((s) => s.setPanelTab);
  const activeFile = useStore((s) => s.activeFile);
  const setActiveFile = useStore((s) => s.setActiveFile);
  const restoreVersion = useStore((s) => s.restoreVersion);
  const select = useStore((s) => s.select);
  const [viewing, setViewing] = useState<string | null>(null);
  const [install, setInstall] = useState(false);
  const servers = useStore((s) => s.servers);
  const realBuilds = useStore((s) => s.realBuilds);
  const realFiles = useStore((s) => s.realFiles);
  const loadRealFiles = useStore((s) => s.loadRealFiles);

  useEffect(() => setViewing(null), [modId]);

  const streaming = isJobLive(job) && job!.modId === modId;
  const viewed = viewing ? versions.find((v) => v.id === viewing) : undefined;
  const shown = viewed ?? active;
  // Nxeon: a real version's code loads from the build service the first time it is shown.
  const realV = shown?.real;
  const realState = realV ? realFiles[realV.buildId] : undefined;
  useEffect(() => {
    if (!realV || streaming || !isTerminal(realV.status) || !realV.paths.length) return;
    void loadRealFiles(realV.buildId, realV.paths.map((p) => p.path));
  }, [realV, streaming, loadRealFiles]);
  const realBuild = realV ? realBuilds.find((b) => b.id === realV.buildId) : undefined;
  const builtOk = realV?.status === "succeeded";
  const files = streaming ? job!.files : (shown?.files ?? []);
  const writingPath = streaming ? job!.activeFile : undefined;
  const current = files.find((f) => f.path === activeFile) ?? files.find((f) => f.path === writingPath) ?? files[0];

  if (!mod) {
    return (
      <PanelShell>
        <div className="grid flex-1 place-items-center p-8 text-[13px] text-cy-muted">
          This mod is no longer in the network.
          <button type="button" onClick={onClose} className="cy5-btn-ghost mt-3 px-3 py-1.5">
            Close
          </button>
        </div>
      </PanelShell>
    );
  }

  const game = getGame(mod.gameId) ?? { id: mod.gameId, name: "Unknown game", short: "Game", rgb: "167 139 250" };
  const cat = CATEGORY_BY_KEY[mod.category];

  const download = () => {
    // A real plugin downloads as the built .jar; its source as the build service's zip.
    if (realV) {
      if (builtOk) window.location.href = `/api/mod-builder/builds/${realV.buildId}/jar`;
      return;
    }
    if (!files.length) return;
    downloadBlob(zipFiles(files), `${slugify(mod.name)}-${shown?.label ?? "draft"}.zip`);
  };
  const downloadSource = () => {
    if (realV) {
      if (builtOk) window.location.href = `/api/mod-builder/builds/${realV.buildId}/source-zip`;
      return;
    }
    download();
  };

  const counts: Partial<Record<PanelTab, number>> = { files: files.length, versions: versions.length };

  return (
    <PanelShell>
      <header className="tint hairline-top px-5 pt-5" style={{ ["--c" as string]: cat.rgb }}>
        <div className="flex items-start gap-3">
          <span
            className="mt-0.5 grid h-11 w-11 shrink-0 rotate-45 place-items-center rounded-[13px] text-[21px]"
            style={{ color: "var(--cc)", background: `rgb(${cat.rgb} / 0.14)`, boxShadow: `inset 0 0 0 1px rgb(${cat.rgb} / 0.45), 0 0 24px rgb(${cat.rgb} / 0.35)` }}
          >
            <CategoryIcon k={cat.key} className="-rotate-45" />
          </span>
          <div className="min-w-0 flex-1">
            <nav className="flex items-center gap-1 text-[11px] text-cy-muted">
              <button type="button" className="hover:text-cy-ink" onClick={() => select({ level: "game", gameId: game.id })}>
                {game.name}
              </button>
              <span className="text-cy-faint">›</span>
              <button type="button" className="hover:text-cy-ink" onClick={() => select({ level: "category", gameId: game.id, category: cat.key })}>
                {cat.label}
              </button>
            </nav>
            <h2 className="truncate font-cy-display text-[19px] font-semibold leading-tight text-cy-ink">{mod.name}</h2>
            <p className="mt-0.5 line-clamp-1 text-[12px] text-cy-ink-2">{mod.summary}</p>
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {streaming ? (
              <span className="flex items-center gap-1.5 rounded-full bg-cy-cyan/10 px-2.5 py-1 text-[11px] font-medium text-cy-cyan">
                <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-cy-cyan" />
                Forging v{job!.version}
              </span>
            ) : (
              shown && (
                <span className="rounded-full px-2.5 py-1 text-[11px] font-semibold" style={{ color: "var(--cc-ink)", background: `rgb(${cat.rgb} / 0.13)` }}>
                  {shown.label}
                </span>
              )
            )}
            {realV && builtOk && !streaming && (
              <button
                type="button"
                onClick={() => setInstall(true)}
                className="hidden h-8 items-center gap-1.5 rounded-lg px-2.5 text-[12px] font-semibold text-white transition hover:brightness-110 sm:inline-flex"
                style={{ background: "linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4)", boxShadow: "0 0 18px rgb(139 92 246 / 0.45)" }}
                title="Install this version on one of your servers"
              >
                Deploy
              </button>
            )}
            <button
              type="button"
              onClick={download}
              disabled={streaming || (realV ? !builtOk : !files.length)}
              className="cy5-btn-ghost h-9 w-9 text-cy-muted disabled:opacity-40"
              aria-label={realV ? "Download .jar" : "Download zip"}
              title={realV ? (realV.jarName ? `Download ${realV.jarName}` : "Download .jar") : "Download .zip"}
            >
              <DownloadIcon />
            </button>
            <button type="button" onClick={onClose} className="cy5-btn-ghost h-9 w-9 text-cy-muted" aria-label="Close panel">
              <CloseIcon />
            </button>
          </div>
        </div>

        <div role="tablist" className="mt-4 flex gap-1">
          {TABS.map((t) => {
            const on = t.id === tab;
            return (
              <button
                key={t.id}
                role="tab"
                aria-selected={on}
                type="button"
                onClick={() => setTab(t.id)}
                className={`relative flex items-center gap-1.5 rounded-t-lg px-3 pb-2.5 pt-1.5 text-[12.5px] font-medium transition ${on ? "text-cy-ink" : "text-cy-muted hover:text-cy-ink-2"}`}
              >
                <span className={on ? "text-cy-accent" : ""}>{t.icon}</span>
                {t.label}
                {counts[t.id] !== undefined && (
                  <span className="rounded-md bg-[rgb(var(--glow)/0.1)] px-1.5 text-[10px] tabular-nums text-cy-muted">{counts[t.id]}</span>
                )}
                {on && <span className="absolute inset-x-2 bottom-0 h-[2px] rounded-full bg-gradient-to-r from-cy-accent via-cy-pink to-cy-cyan shadow-[0_0_10px_var(--accent)]" />}
              </button>
            );
          })}
        </div>
      </header>
      <div className="h-px bg-cy-line" />

      {viewed && !streaming && (
        <div className="flex items-center gap-2 border-b border-cy-line bg-[rgb(var(--glow)/0.06)] px-4 py-2 text-[12px] text-cy-ink-2">
          <HistoryIcon className="text-cy-accent" /> Viewing {viewed.label} (read-only)
          <button type="button" onClick={() => restoreVersion(mod.id, viewed.id)} className="ml-auto font-medium text-cy-accent-ink hover:underline">
            Restore
          </button>
          <button type="button" onClick={() => setViewing(null)} className="font-medium text-cy-muted hover:text-cy-ink">
            Back to current
          </button>
        </div>
      )}

      {tab === "code" && realV && !streaming && realV.status === "failed" ? (
        <div className="grid flex-1 place-items-center p-8 text-center">
          <div className="max-w-[44ch]">
            <div className="font-cy-display text-[15px] font-semibold text-cy-ink">This version didn&apos;t build</div>
            <p className="mt-1.5 text-[12.5px] leading-relaxed text-cy-ink-2">{realV.error || "The build stopped before it finished."}</p>
            <p className="mt-2 text-[11.5px] text-cy-muted">Tokens it held went back to you. Describe the change again in the prompt to try once more.</p>
          </div>
        </div>
      ) : tab === "code" &&
        (current ? (
          <>
            <FileTabs files={files} active={current.path} writing={writingPath} onPick={setActiveFile} />
            <CodeView file={current} writing={streaming && current.path === writingPath} />
          </>
        ) : (
          <div className="grid flex-1 place-items-center p-8 text-center text-[13px] text-cy-muted">
            {streaming ? (
              <span className="shimmer-text">Cyrus is planning the files…</span>
            ) : realV && (realState === "loading" || (realState === undefined && realV.paths.length > 0)) ? (
              <span className="shimmer-text">Loading the code…</span>
            ) : realState === "error" ? (
              "The builder didn't answer. Try again in a moment."
            ) : (
              "No code yet."
            )}
          </div>
        ))}
      {tab === "files" && (
        <FilesTab
          files={files}
          active={current?.path}
          writing={writingPath}
          onOpen={(p) => {
            setActiveFile(p);
            setTab("code");
          }}
          onDownload={downloadSource}
        />
      )}
      {tab === "versions" && (
        <VersionsTab
          versions={versions}
          activeId={active?.id}
          job={streaming ? job : null}
          rgb={cat.rgb}
          onRestore={(id) => {
            restoreVersion(mod.id, id);
            setViewing(null);
          }}
          onView={(id) => {
            setViewing(id === active?.id ? null : id);
            setTab("code");
          }}
        />
      )}
      {tab === "notes" && <NotesTab mod={mod} version={shown} />}
      {install && realBuild && <InstallModal build={realBuild} servers={servers} onClose={() => setInstall(false)} onDone={() => void useStore.getState().refreshReal()} />}
    </PanelShell>
  );
}

