export const visibleSource = (files: { path: string; size: number }[]) =>
  files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json");

export function versionOf(b: ModBuildView, n: number): ModVersion {
  const s = b.result?.summary;
  return {
    id: b.id,
    label: `v${n}`,
    createdAt: Date.parse(b.createdAt),
    model: modelOf(b),
    credits: 0,
    prompt: b.changeRequest || b.prompt,
    summary: s?.changes || s?.tagline || (b.status === "failed" ? b.error || "This version didn't build." : b.changeRequest || b.prompt),
    files: [],
    additions: 0,
    deletions: 0,
    real: {
      buildId: b.id,
      status: b.status,
      mcVersion: b.mcVersion,
      jarName: b.jarName,
      jarSize: b.jarSize,
      error: b.error,
      attempts: b.attempts,
      durationMs: b.durationMs,
      paths: visibleSource(b.result?.files ?? []),
    },
  };
}

/** Cyrus's notes for a real build, from what the build service reported. */
export function realNotes(b: ModBuildView | null): string {
  if (!b) return "";
  if (b.status === "failed") return `# Didn't build\n\n${b.error || "The build stopped before it finished."}\n\nTokens held for a failed build go back to you.`;
  if (!isTerminal(b.status)) return "# Building\n\nCyrus is writing, compiling and safety-checking this version right now.";
  const r = b.result;
  const s = r?.summary;
  const out: string[] = [`# ${b.pluginName || "Your plugin"}${b.version ? ` v${b.version}` : ""}`];
  if (s?.text) out.push("", s.text);
  if (s?.howToUse?.length) out.push("", "## How to use", ...s.howToUse.map((x) => `- ${x}`));
  if (r?.commands?.length) out.push("", "## Commands", ...r.commands.map((c) => `- \`${c.usage}\` ${c.description}${c.permission ? ` (\`${c.permission}\`)` : ""}`));
  if (r?.permissions?.length) out.push("", "## Permissions", ...r.permissions.map((p) => `- \`${p.node}\` ${p.description} (default: ${p.default})`));
  if (r?.config?.length) out.push("", "## Config", ...r.config.map((c) => `- \`${c.key}\` ${c.description} (default \`${c.default}\`)`));
  if (s?.limitations?.length) out.push("", "## Limits", ...s.limitations.map((x) => `- ${x}`));
  const safety = r?.safety?.verdict;
  out.push("", "## Build", `- Paper ${b.mcVersion} · built in ${Math.max(1, Math.round((b.durationMs ?? 0) / 1000))}s${b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}`);
  if (safety) out.push(`- Safety check: **${safety === "pass" ? "passed" : safety === "warn" ? "passed with notes" : "blocked"}** (no internet, no system access)`);
  return out.join("\n");
}

