import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { modBuilderMetadata, requireModBuilderUser } from "@/lib/modbuilder/access";
import { svcHealth } from "@/lib/modbuilder/client";
import { syncBuild, toView } from "@/lib/modbuilder/store";
import { isTerminal } from "@/lib/modbuilder/types";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { CyrusApp } from "@/components/cyrus/CyrusApp";

export const cyrusMetadata = () => modBuilderMetadata("Cyrus · AI mod studio");

/** Server half of both Cyrus routes: gate, load every build of the user, advance in-flight ones. */
export async function CyrusPage(selectedId: string | null) {
  const user = await requireModBuilderUser();
  const [rows, health, servers] = await Promise.all([
    db.modBuild.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 200 }),
    svcHealth(),
    modBuilderServers(user.id),
  ]);
  if (selectedId && !rows.some((r) => r.id === selectedId)) notFound();
  const fresh = await Promise.all(rows.map((r) => (isTerminal(r.status) ? r : syncBuild(r).catch(() => r))));
  return <CyrusApp initialBuilds={fresh.map(toView)} servers={servers} online={!!health?.ok} userId={user.id} selectedId={selectedId} />;
}

